import http from 'node:http';import fs from 'node:fs';import path from 'node:path';
const root=process.cwd();http.createServer((req,res)=>{let p=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(!p.startsWith(root+path.sep)&&p!==root){res.writeHead(403).end();return;}if(fs.existsSync(p)&&fs.statSync(p).isDirectory())p=path.join(p,'index.html');if(!fs.existsSync(p)){res.writeHead(404).end();return;}res.setHeader('Content-Type',({'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.jpg':'image/jpeg','.pdf':'application/pdf'})[path.extname(p)]||'application/octet-stream');fs.createReadStream(p).pipe(res);}).listen(8765,'127.0.0.1',()=>console.log('http://127.0.0.1:8765/catalog/'));
